<?php require_once __DIR__.'/includes/common.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $u=$_POST['username']??''; $e=$_POST['email']??''; $p=$_POST['password']??''; $c=$_POST['password_confirm']??''; if($p!==$c){echo '<script>alert("密碼不一致")</script>';} else {try{$st=db()->prepare('INSERT INTO users(username,email,password_hash) VALUES(?,?,?)');$st->execute([$u,$e,password_hash($p,PASSWORD_BCRYPT)]); header('Location:login.php'); exit;}catch(Throwable $t){echo '<script>alert("註冊失敗")</script>';}}}
?><form class="register-form" method="post"><input class="username-input" name="username"><input class="email-input" name="email"><input class="password-input" type="password" name="password"><input class="password-confirm-input" type="password" name="password_confirm"><button class="register-submit" type="submit">註冊</button></form>
